  'After every test, see how many you got right and which topics need more practice.': 'ᱥᱟᱨᱦᱟᱣ ᱴᱮᱥᱴ ᱪᱷᱚᱭ ᱪᱮᱫ ᱥᱟᱱᱟᱢ ᱴᱷᱤᱠ ᱟᱨ ᱪᱮᱫ ᱴᱚᱯᱤᱠ ᱨᱮ ᱟᱨᱦᱚᱸ ᱯᱨᱮᱠᱴᱤᱥ ᱞᱟᱹᱠᱛᱤ ᱧᱮᱞ ᱢᱮ.',
