  'Invite your friends to AajExam. Earn cash rewards every time a friend upgrades to PRO.': 'ᱟᱢᱟᱜ ᱵᱚᱱᱫᱷᱩ ᱠᱚ AajExam ᱨᱮ ᱵᱟᱹᱱᱩᱜ ᱢᱮ. ᱢᱤᱫ ᱵᱚᱱᱫᱷᱩ PRO ᱞᱟᱹᱠᱛᱤ ᱚᱠᱛᱚ ᱠᱮᱥ ᱨᱤᱣᱟᱨᱰ ᱧᱟᱢ ᱢᱮ.',
  'Start referring': 'ᱨᱮᱯᱷᱮᱨ ᱮᱛᱦᱚᱵ ᱢᱮ',
  'Study with': 'ᱯᱟᱲᱦᱟᱣ ᱢᱮ',
  'Confidence.': 'ᱵᱤᱥᱣᱟᱥ ᱥᱟᱶᱛᱮ.',
  'Daily Goals': 'ᱥᱟᱨᱦᱟᱣ ᱞᱟᱠᱷᱭᱟ',
  'Set a small goal for each day and complete it. Small steps lead to big results.': 'ᱥᱟᱨᱦᱟᱣ ᱞᱟᱹᱜᱤᱫ ᱦᱩᱰᱤᱧ ᱞᱟᱠᱷᱭᱟ ᱵᱟᱪᱷᱟᱣ ᱢᱮ ᱟᱨ ᱯᱩᱨᱟᱹᱣ ᱢᱮ. ᱦᱩᱰᱤᱧ ᱯᱟᱦᱴᱟ ᱢᱟᱨᱟᱝ ᱯᱷᱚᱞ ᱮᱢᱟ.',
  'Study with Others': 'ᱮᱴᱟᱜ ᱠᱚ ᱥᱟᱶ ᱯᱟᱲᱦᱟᱣ ᱢᱮ',
  'Study with thousands of students who want to pass the same exams as you.': 'ᱟᱢ ᱞᱮᱠᱟᱱᱮ ᱥᱚᱢᱟᱱ ᱯᱨᱤᱠᱷᱟ ᱯᱟᱥ ᱞᱟᱹᱜᱤᱫ ᱪᱮᱛ ᱦᱚᱡᱟᱨ ᱪᱟᱛᱨᱚ ᱥᱟᱶ ᱯᱟᱲᱦᱟᱣ ᱢᱮ.',
  'Detailed Solutions': 'ᱵᱤᱵᱨᱚᱬ ᱛᱮᱞᱟ',
  'Get in-depth explanations for every question to understand concepts better.': 'ᱥᱟᱱᱟᱢ ᱠᱩᱞᱤ ᱨᱮᱱᱟᱜ ᱠᱷᱚᱞᱟᱹ ᱵᱟᱰᱟᱭ ᱧᱟᱢ ᱢᱮ, ᱠᱚᱱᱥᱮᱯᱴ ᱵᱷᱟᱞᱮ ᱵᱩᱡᱷᱟᱣ ᱞᱟᱹᱜᱤᱫ.',
