  'You can upgrade anytime.': 'ᱟᱢ ᱚᱠᱛᱚ ᱟᱯᱜᱨᱮᱰ ᱫᱟᱲᱮ.',
  'You\'ve seen {count} sample questions. Create a free account in 30 seconds to attempt the full paper with timer, scoring, and detailed solutions.': 'ᱟᱢ {count} ᱱᱚᱢᱩᱱᱟ ᱠᱩᱞᱤ ᱧᱮᱞ ᱠᱮᱜᱟ. ᱴᱟᱭᱢᱟᱨ, ᱥᱠᱳᱨᱤᱝ ᱟᱨ ᱵᱤᱵᱨᱚᱬ ᱛᱮᱞᱟ ᱥᱟᱶᱛᱮ ᱯᱩᱨᱟᱹ ᱠᱷᱟᱛᱟ ᱥᱟᱯᱷᱟ ᱞᱟᱹᱜᱤᱫ 30 ᱥᱮᱠᱮᱱᱰ ᱨᱮ ᱵᱷᱟᱲᱟᱣ ᱵᱟᱝ ᱮᱠᱟᱣᱱᱴ ᱛᱮᱭᱟᱨ ᱢᱮ.',
  'Your Profile': 'ᱟᱢᱟᱜ ᱯᱨᱚᱯᱷᱟᱭᱤᱞ',
  'Your bank details are only used to send your reward money. They are kept safe.': 'ᱟᱢᱟᱜ ᱵᱮᱸᱠ ᱵᱤᱵᱨᱚᱬ ᱨᱤᱣᱟᱨᱰ ᱯᱩᱭᱥᱟ ᱵᱷᱮᱡᱟᱜ ᱞᱟᱹᱜᱤᱫ ᱜᱮ ᱵᱮᱵᱷᱟᱨ ᱦᱩᱭᱟ. ᱱᱚᱣᱟ ᱨᱩᱠᱷᱤᱭᱟ ᱛᱮ ᱛᱟᱦᱮᱱ ᱟᱠᱟᱱᱟ.',
  'Your current plan': 'ᱟᱢᱟᱜ ᱱᱤᱛᱚᱜ ᱯᱞᱟᱱ',
