  'Your payment is still pending. Please wait a little longer or check again from the subscription page.': 'ᱟᱢᱟᱜ ᱯᱮᱢᱮᱱᱴ ᱱᱤᱛᱚᱜ ᱵᱟᱠᱤ ᱢᱮᱱᱟᱭ. ᱡᱟᱹᱜᱟ ᱛᱟᱦᱮᱱ ᱢᱮ ᱥᱮ ᱥᱟᱵᱥᱠᱨᱤᱯᱥᱚᱱ ᱥᱟᱦᱴᱟ ᱠᱷᱚᱱ ᱫᱚᱦᱲᱟ ᱧᱮᱞ ᱢᱮ.',
