  ', AajExam is 100% based on your knowledge and hard work. Everything you earn here is through your own effort. We follow all rules to make sure the platform is safe, fair, and honest for every student.': ', AajExam ᱯᱩᱨᱟᱹ ᱟᱢᱟᱜ ᱜᱭᱟᱱ ᱟᱨ ᱠᱷᱟᱴᱤᱱ ᱠᱟᱹᱢᱤ ᱨᱮ ᱠᱷᱟᱱ ᱵᱟᱨᱥᱤᱭᱟ. ᱱᱚᱸᱰᱮ ᱟᱢ ᱪᱮᱫ ᱧᱟᱢ ᱮᱫᱟ ᱥᱟᱱᱟᱢ ᱟᱢᱟᱜ ᱟᱡᱟᱜ ᱪᱮᱥᱴᱟ ᱛᱮ. ᱟᱞᱮ ᱡᱷᱚᱛᱚ ᱱᱤᱭᱚᱢ ᱯᱟᱞᱟᱱ ᱮᱫᱟ ᱪᱟᱛᱨᱚ ᱞᱟᱹᱜᱤᱫ ᱨᱩᱠᱷᱤᱭᱟ, ᱱᱤᱭᱟᱭ ᱟᱨ ᱥᱟᱹᱠᱷᱤ ᱞᱮᱠᱟ ᱛᱟᱦᱮᱱ ᱞᱟᱹᱜᱤᱫ.',
  'A Government Registered Company (UDYAM)': 'ᱥᱟᱨᱠᱟᱨ ᱨᱮ ᱨᱮᱡᱤᱥᱴᱟᱨ ᱠᱚᱢᱯᱟᱱᱤ (UDYAM)',
  'A:': 'ᱛᱮ:',
  'Q:': 'ᱠᱩ:',
  'AajExam Team': 'AajExam ᱴᱤᱢ',
  'AajExam helps students across India prepare for government exams. We believe every student deserves good study material, no matter where they come from.': 'AajExam ᱵᱷᱟᱨᱚᱛ ᱨᱮᱱᱟᱜ ᱪᱟᱛᱨᱚ ᱠᱚ ᱥᱟᱨᱠᱟᱨᱤ ᱯᱨᱤᱠᱷᱟ ᱛᱤᱭᱟᱨᱤ ᱨᱮ ᱜᱚᱲᱚ ᱮᱫᱟ. ᱟᱞᱮ ᱵᱤᱥᱣᱟᱥ ᱮᱫᱟ ᱡᱷᱚᱛᱚ ᱪᱟᱛᱨᱚ ᱵᱷᱟᱞᱮ ᱯᱟᱲᱦᱟᱣ ᱥᱟᱢᱜᱨᱤ ᱞᱟᱹᱜᱤᱫ ᱯᱟᱛᱨᱚ, ᱚᱠᱟᱭ ᱴᱷᱟᱶ ᱠᱷᱚᱱ ᱟᱹᱭᱩᱨ ᱠᱷᱟᱱ ᱦᱚᱸ.',
  'AajExam is about your knowledge and your hard work. The more you study and practice, the better your score. Only your effort takes you to the top.': 'AajExam ᱟᱢᱟᱜ ᱜᱭᱟᱱ ᱟᱨ ᱠᱷᱟᱴᱤᱱ ᱠᱟᱹᱢᱤ ᱵᱟᱵᱚᱛ. ᱟᱢ ᱡᱤᱛᱚᱠ ᱯᱟᱲᱦᱟᱣ ᱟᱨ ᱯᱨᱮᱠᱴᱤᱥ ᱮᱫᱟ, ᱥᱠᱳᱨ ᱛᱤᱱᱟᱜ ᱵᱷᱟᱞᱮ ᱦᱩᱭᱟ. ᱟᱢᱟᱜ ᱪᱮᱥᱴᱟ ᱜᱮ ᱟᱢ ᱪᱤᱠᱤ ᱥᱮᱱ ᱮᱫᱟ.',
  'About Us | Last Updated February 2026': 'ᱟᱞᱮᱠᱷᱟᱛᱮ ᱵᱟᱵᱚᱛ | ᱢᱟᱨᱟᱝ ᱟᱯᱰᱮᱴ ᱯᱷᱮᱵᱨᱩᱣᱟᱨᱤ 2026',
  'About the Founder': 'ᱥᱟᱠᱟᱢ ᱵᱟᱵᱚᱛ',
  'All Subjects Covered': 'ᱡᱷᱚᱛᱚ ᱵᱤᱥᱚᱭ ᱥᱮᱞᱮᱫ',
  'All articles': 'ᱡᱷᱚᱛᱚ ᱞᱮᱠᱷᱟ',
  'All government exams': 'ᱡᱷᱚᱛᱚ ᱥᱟᱨᱠᱟᱨᱤ ᱯᱨᱤᱠᱷᱟ',
  'As a UDYAM registered entrepreneur, Sazid combines technical expertise with business acumen to create scalable, user-friendly educational solutions. His vision is to democratize access to high-quality government exam preparation resources, ensuring that students from all backgrounds have the tools they need to succeed in competitive examinations.': 'UDYAM ᱨᱮᱡᱤᱥᱴᱟᱨ ᱵᱷᱟᱢᱤ ᱞᱮᱠᱟ, ᱥᱟᱡᱤᱫ ᱴᱮᱠᱱᱤᱠᱟᱞ ᱠᱟᱹᱢᱤ ᱟᱨ ᱵᱤᱡᱽᱱᱮᱥ ᱵᱩᱫᱷᱤ ᱥᱟᱶ ᱥᱟᱱᱟᱢ ᱵᱷᱟᱞᱮ ᱵᱷᱟᱨ ᱥᱮᱞᱮᱫ ᱠᱟᱛᱮ ᱥᱤᱠᱷᱟ ᱥᱮᱞᱩᱥᱚᱱ ᱛᱮᱭᱟᱨ ᱮᱫᱟ. ᱟᱡᱟᱜ ᱞᱟᱠᱷᱭᱟ ᱵᱷᱟᱞᱮ ᱥᱟᱨᱠᱟᱨᱤ ᱯᱨᱤᱠᱷᱟ ᱛᱤᱭᱟᱨᱤ ᱥᱟᱱᱟᱢ ᱞᱟᱹᱜᱤᱫ ᱥᱚᱡᱷᱮ ᱠᱟᱛᱮ ᱮᱢ, ᱡᱷᱚᱛᱚ ᱪᱟᱛᱨᱚ ᱯᱨᱤᱠᱷᱟ ᱨᱮ ᱡᱤᱛ ᱞᱟᱹᱜᱤᱫ ᱞᱟᱹᱠᱛᱤ ᱞᱟᱹᱠᱛᱤ ᱥᱟᱢᱟᱱ ᱧᱟᱢ ᱞᱟᱹᱜᱤᱫ.',
  'Author': 'ᱚᱞᱤᱭᱟ',
  'Blog Not Found': 'ᱵᱞᱚᱜ ᱵᱟᱝ ᱧᱟᱢᱠᱟᱱᱟ',
  'Browse All Blogs': 'ᱡᱷᱚᱛᱚ ᱵᱞᱚᱜ ᱧᱮᱞ ᱢᱮ',
  'Can\'t find the answer you\'re looking for? Our support team is here to help!': 'ᱟᱢ ᱥᱮᱸᱫᱽᱨᱟ ᱛᱮᱞᱟ ᱵᱟᱝ ᱧᱟᱢ ᱠᱮᱜ ᱟ ᱥᱮ? ᱟᱞᱮᱜ ᱜᱚᱲᱚ ᱴᱤᱢ ᱱᱚᱸᱰᱮ ᱢᱮᱱᱟᱭ!',
  'Comprehensive exam preparation materials and practice tests.': 'ᱯᱨᱤᱠᱷᱟ ᱛᱤᱭᱟᱨᱤ ᱨᱮᱱᱟᱜ ᱯᱩᱨᱟᱹ ᱥᱟᱢᱜᱨᱤ ᱟᱨ ᱯᱨᱮᱠᱴᱤᱥ ᱴᱮᱥᱴ.',
  'Connect with Sazid': 'ᱥᱟᱡᱤᱫ ᱥᱟᱶ ᱡᱚᱜᱟᱡᱚᱜ ᱢᱮ',
  'Designed for your study success': 'ᱟᱢᱟᱜ ᱯᱟᱲᱦᱟᱣ ᱡᱤᱛ ᱞᱟᱹᱜᱤᱫ ᱵᱮᱱᱟᱣ ᱟᱠᱟᱱᱟ',
  'Educational Philosophy': 'ᱥᱤᱠᱷᱟ ᱫᱚᱨᱥᱚᱱ',
  'Email Address': 'ᱤᱢᱮᱞ ᱴᱷᱤᱠᱟᱱᱟ',
  'Enforced on the server — locked content shows a real upgrade gate, not just a hidden button': 'ᱥᱟᱨᱵᱟᱨ ᱨᱮ ᱞᱟᱹᱜᱩ — ᱞᱚᱠ ᱥᱟᱢᱜᱨᱤ ᱨᱮ ᱥᱟᱹᱠᱷᱤ ᱟᱯᱜᱨᱮᱰ ᱜᱮᱴ ᱧᱮᱞᱚᱜ, ᱞᱩᱠᱟᱹᱭ ᱵᱚᱴᱚᱱ ᱵᱟᱝ',
  'Error sending message. Please try again.': 'ᱵᱟᱨᱛᱟ ᱵᱷᱮᱡᱟᱜ ᱨᱮ ᱵᱷᱩᱞ. ᱫᱚᱦᱲᱟ ᱪᱮᱥᱴᱟ ᱢᱮ.',
  'Everything you need to start preparing today, no card required.': 'ᱱᱤᱛᱚᱜ ᱛᱤᱭᱟᱨᱤ ᱮᱛᱦᱚᱵ ᱞᱟᱹᱜᱤᱫ ᱡᱷᱚᱛᱚ ᱞᱟᱹᱠᱛᱤ, ᱠᱟᱨᱰ ᱵᱟᱝ ᱞᱟᱹᱠᱛᱤ.',
  'Exam preparation tips, guides & insights': 'ᱯᱨᱤᱠᱷᱟ ᱛᱤᱭᱟᱨᱤ ᱴᱤᱯ, ᱜᱟᱭᱤᱰ ᱟᱨ ᱵᱩᱫᱷᱤ',
