  'Feature': 'ᱯᱷᱤᱪᱟᱨ',
  'Featured': 'ᱵᱤᱥᱮᱥ',
  'Find Us on Social Media': 'ᱥᱚᱥᱤᱭᱟᱞ ᱢᱤᱰᱤᱭᱟ ᱨᱮ ᱟᱞᱮ ᱧᱟᱢ ᱢᱮ',
  'Find answers to common questions about AajExam platform, subscriptions, and exam preparation': 'AajExam ᱯᱞᱮᱴᱯᱷᱚᱨᱢ, ᱥᱟᱵᱥᱠᱨᱤᱯᱥᱚᱱ ᱟᱨ ᱯᱨᱤᱠᱷᱟ ᱛᱤᱭᱟᱨᱤ ᱵᱟᱵᱚᱛ ᱥᱟᱫᱷᱟᱨᱚᱱ ᱠᱩᱞᱤ ᱨᱮᱱᱟᱜ ᱛᱮᱞᱟ ᱧᱟᱢ ᱢᱮ',
  'First, try clearing your browser cache and cookies, or try a different browser. If issues persist, contact our support team at {email} with details about the problem, your device, and browser information.': 'ᱢᱟᱲᱟᱝ ᱟᱢᱟᱜ ᱵᱨᱟᱡᱟᱨ ᱠᱮᱪ ᱟᱨ ᱠᱩᱠᱤ ᱯᱩᱥᱟᱨ ᱢᱮ ᱥᱮ ᱮᱴᱟᱜ ᱵᱨᱟᱡᱟᱨ ᱪᱮᱥᱴᱟ ᱢᱮ. ᱥᱚᱢᱥᱭᱟ ᱛᱟᱦᱮᱱ ᱠᱷᱟᱱ, ᱥᱚᱢᱥᱭᱟ, ᱟᱢᱟᱜ ᱰᱤᱵᱷᱟᱭᱤᱥ ᱟᱨ ᱵᱨᱟᱡᱟᱨ ᱵᱤᱵᱨᱚᱬ ᱥᱟᱶᱛᱮ {email} ᱨᱮ ᱟᱞᱮᱜ ᱜᱚᱲᱚ ᱴᱤᱢ ᱥᱟᱶ ᱡᱚᱜᱟᱡᱚᱜ ᱢᱮ.',
  'Follow Us': 'ᱟᱞᱮ ᱯᱷᱚᱞᱚ ᱢᱮ',
  'For Every Student': 'ᱡᱷᱚᱛᱚ ᱪᱟᱛᱨᱚ ᱞᱟᱹᱜᱤᱫ',
  'Founder & CEO, AajExam': 'ᱥᱟᱠᱟᱢ ᱟᱨ CEO, AajExam',
  'Free forever': 'ᱚᱠᱛᱚ ᱵᱷᱟᱲᱟᱣ ᱵᱟᱝ',
  'Free practice quizzes': 'ᱵᱷᱟᱲᱟᱣ ᱵᱟᱝ ᱯᱨᱮᱠᱴᱤᱥ ᱠᱣᱤᱡ',
  'Full feature comparison': 'ᱯᱩᱨᱟᱹ ᱯᱷᱤᱪᱟᱨ ᱢᱤᱞᱟᱣ',
  'Full-Stack Developer | Educational Technology Expert | UDYAM Registered Entrepreneur': 'ᱯᱷᱩᱞ-ᱥᱴᱮᱠ ᱰᱮᱵᱷᱮᱞᱚᱯᱟᱨ | ᱥᱤᱠᱷᱟ ᱴᱮᱠᱱᱚᱞᱚᱡᱤ ᱵᱤᱥᱮᱥᱚᱡ | UDYAM ᱨᱮᱡᱤᱥᱴᱟᱨ ᱵᱷᱟᱢᱤ',
  'Get Started Now': 'ᱱᱤᱛᱚᱜ ᱮᱛᱦᱚᱵ ᱢᱮ',
  'Get started free': 'ᱵᱷᱟᱲᱟᱣ ᱵᱟᱝ ᱮᱛᱦᱚᱵ ᱢᱮ',
  'GitHub': 'GitHub',
  'Govt Exams Preparation': 'ᱥᱟᱨᱠᱟᱨᱤ ᱯᱨᱤᱠᱷᱟ ᱛᱤᱭᱟᱨᱤ',
  'Have a question or problem? Talk to us. We are happy to help you.': 'ᱠᱩᱞᱤ ᱥᱮ ᱥᱚᱢᱥᱭᱟ ᱢᱮᱱᱟᱭ ᱫᱚ? ᱟᱞᱮ ᱥᱟᱶ ᱵᱟᱛᱠᱷᱟᱛ ᱢᱮ. ᱟᱢ ᱜᱚᱲᱚ ᱮᱢ ᱞᱟᱹᱜᱤᱫ ᱟᱞᱮ ᱠᱷᱩᱥᱤ ᱢᱮᱱᱟᱭ.',
  'He advocates for a balanced approach that combines technology-enabled convenience with pedagogically sound learning principles. He personally oversees the editorial process and ensures all content meets rigorous standards.': 'ᱤᱱ ᱴᱮᱠᱱᱚᱞᱚᱡᱤ ᱥᱩᱵᱤᱫᱷᱟ ᱟᱨ ᱥᱤᱠᱷᱟ ᱨᱮᱱᱟᱜ ᱴᱷᱤᱠ ᱥᱤᱫᱷᱟᱱᱛ ᱢᱤᱞᱟᱣ ᱞᱟᱹᱜᱤᱫ ᱥᱟᱢᱛᱩᱞᱤᱛ ᱥᱚᱢᱨᱤᱯᱛᱚ ᱨᱮ ᱛᱷᱟᱯᱟ ᱮᱫᱟ. ᱤᱱ ᱟᱡ ᱥᱟᱢᱯᱟᱫᱚᱱ ᱯᱨᱚᱠᱨᱤᱭᱟ ᱧᱮᱞ ᱮᱫᱟ ᱟᱨ ᱡᱷᱚᱛᱚ ᱥᱟᱢᱜᱨᱤ ᱠᱷᱟᱴᱤᱱ ᱢᱟᱯ ᱯᱩᱨᱟᱹ ᱦᱩᱭ ᱞᱟᱹᱜᱤᱫ ᱵᱷᱟᱥ ᱮᱫᱟ.',
  'How We Help You': 'ᱟᱞᱮ ᱟᱢ ᱠᱮᱱ ᱪᱮᱫ ᱞᱮᱠᱟ ᱜᱚᱲᱚ ᱮᱫᱟ',
  'How can we help?': 'ᱟᱞᱮ ᱪᱮᱫ ᱞᱮᱠᱟ ᱜᱚᱲᱚ ᱮᱢ ᱫᱟᱲᱮ?',
  'If you encounter an error in a test question or believe an answer is incorrect, please report it through the feedback option available after test completion, or email us at {email} with the test name and question details.': 'ᱴᱮᱥᱴ ᱠᱩᱞᱤ ᱨᱮ ᱵᱷᱩᱞ ᱧᱟᱢ ᱠᱷᱟᱱ ᱥᱮ ᱛᱮᱞᱟ ᱵᱷᱩᱞ ᱞᱮᱠᱟ ᱡᱟᱱᱟᱣ ᱠᱷᱟᱱ, ᱴᱮᱥᱴ ᱯᱩᱨᱟᱹ ᱛᱟᱭᱚᱢ ᱯᱷᱤᱰᱵᱮᱠ ᱵᱤᱠᱚᱞᱯᱚ ᱛᱮ ᱨᱤᱯᱚᱨᱴ ᱢᱮ, ᱥᱮ ᱴᱮᱥᱴ ᱧᱩᱛᱩᱢ ᱟᱨ ᱠᱩᱞᱤ ᱵᱤᱵᱨᱚᱬ ᱥᱟᱶᱛᱮ {email} ᱨᱮ ᱤᱢᱮᱞ ᱢᱮ.',
  'Important Note': 'ᱞᱟᱹᱠᱛᱤ ᱚᱞ',
  'Join Thousands of Successful Students': 'ᱡᱤᱛ ᱟᱠᱟᱱ ᱦᱚᱡᱟᱨ ᱪᱟᱛᱨᱚ ᱥᱟᱶ ᱥᱮᱞᱮᱫ ᱢᱮ',
  'Join thousands of students who are already passing exams and earning cash by referring friends to AajExam.': 'ᱯᱨᱤᱠᱷᱟ ᱯᱟᱥ ᱠᱟᱱ ᱟᱨ AajExam ᱨᱮ ᱵᱚᱱᱫᱷᱩ ᱨᱮᱯᱷᱮᱨ ᱠᱟᱛᱮ ᱧᱟᱢ ᱠᱟᱱ ᱦᱚᱡᱟᱨ ᱪᱟᱛᱨᱚ ᱥᱟᱶ ᱥᱮᱞᱮᱫ ᱢᱮ.',
  'Join thousands of students who are already using AajExam to improve their scores and time management.': 'ᱛᱟᱞᱟ ᱟᱨ ᱚᱠᱛᱚ ᱥᱟᱵᱟᱭ ᱥᱩᱫᱷᱨᱟᱣ ᱞᱟᱹᱜᱤᱫ AajExam ᱵᱮᱵᱷᱟᱨ ᱠᱟᱱ ᱦᱚᱡᱟᱨ ᱪᱟᱛᱨᱚ ᱥᱟᱶ ᱥᱮᱞᱮᱫ ᱢᱮ.',
