  '2 per week': 'ᱦᱟᱯᱛᱟ ᱨᱮ 2',
  'Current affairs & exam news': 'ᱠᱚᱨᱮᱱᱴ ᱮᱯᱷᱮᱭᱟᱨᱥ ᱟᱨ ᱯᱨᱤᱠᱷᱟ ᱥᱟᱫᱷᱟᱨ',
