  'AI Study Planner': 'AI ᱥᱴᱚᱰᱤ ᱯᱞᱟᱱᱟᱨ',
  'Revision Queue (spaced repetition)': 'ᱨᱤᱵᱷᱤᱡᱚᱱ ᱠᱣᱤᱭᱩ (ᱫᱷᱤᱢᱤ ᱫᱷᱤᱢᱤ ᱫᱚᱦᱲᱟ)',
  'Mentors (guidance from top scorers)': 'ᱢᱮᱱᱴᱚᱨ (ᱪᱤᱠᱤ ᱥᱠᱳᱨᱟᱨ ᱠᱚ ᱠᱷᱚᱱ ᱜᱚᱲᱚ)',
  'Community & multiplayer': 'ᱠᱚᱢᱤᱭᱩᱱᱤᱴᱤ ᱟᱨ ᱢᱟᱞᱴᱤᱯᱞᱮᱭᱟᱨ',
